class AvgPartition:
    """
    This is a class that partitions the given list into different blocks by specifying the number of partitions, with each block having a uniformly distributed length.
    """

    def __init__(self, lst, limit):
        self.lst = lst
        self.limit = limit

    def setNum(self):
        size = len(self.lst) // self.limit
        remainder = len(self.lst) % self.limit
        return (size, remainder)

    def get(self, index):
        size, remainder = self.setNum()
        # The first 'remainder' partitions get one extra element
        if index < remainder:
            start = index * (size + 1)
            end = start + size + 1
        else:
            start = remainder * (size + 1) + (index - remainder) * size
            end = start + size
        return self.lst[start:end]

