    def __init__(self, text, pattern):
        self.text, self.pattern = text, pattern
        self.textLen, self.patLen = len(text), len(pattern)

    def match_in_pattern(self, char):
        # Find the rightmost occurrence of char in the pattern
        for i in range(self.patLen - 1, -1, -1):
            if self.pattern[i] == char:
                return i
        return -1

    def mismatch_in_text(self, currentPos):
        # Compare pattern against text starting at currentPos
        # Returns the index in the pattern where mismatch occurs, or -1 if full match
        for i in range(self.patLen - 1, -1, -1):
            if self.pattern[i] != self.text[currentPos + i]:
                return i
        return -1

    def bad_character_heuristic(self):
        # Find all occurrences of pattern in text
        positions = []
        if self.patLen == 0:
            # Empty pattern matches at every position including one past end
            for i in range(self.textLen + 1):
                positions.append(i)
            return positions

        i = 0
        while i <= self.textLen - self.patLen:
            mismatch_index = self.mismatch_in_text(i)
            if mismatch_index == -1:
                # Full match found
                positions.append(i)
                i += 1
            else:
                # Bad character heuristic
                bad_char = self.text[i + mismatch_index]
                char_pos = self.match_in_pattern(bad_char)
                if char_pos == -1:
                    i += mismatch_index + 1
                else:
                    i += max(1, mismatch_index - char_pos)
        return positions

