from datetime import datetime, timedelta

class CalendarUtil:
    """
    This is a class as CalendarUtil that provides functionalities to manage calendar events, schedule appointments, and perform conflict checks.
    """

    def __init__(self):
        """
        Initialize the calendar with an empty list of events.
        """
        self.events = []

    def add_event(self, event):
        self.events.append(event)

    def remove_event(self, event):
        if event in self.events:
            self.events.remove(event)

    def get_events(self, date):
        result = []
        for event in self.events:
            event_date = event['date']
            if event_date.year == date.year and event_date.month == date.month and event_date.day == date.day:
                result.append(event)
        return result

    def is_available(self, start_time, end_time):
        for event in self.events:
            event_start = event['start_time']
            event_end = event['end_time']
            # Check for overlap
            if start_time < event_end and end_time > event_start:
                return False
        return True

    def get_available_slots(self, date):
        # Get all events on the given date
        day_start = datetime(date.year, date.month, date.day, 0, 0)
        day_end = datetime(date.year, date.month, date.day, 0, 0) + timedelta(days=1)

        # Get events on this date
        day_events = []
        for event in self.events:
            event_start = event['start_time']
            event_end = event['end_time']
            # Check if event overlaps with this day
            if event_start.date() == date.date():
                day_events.append(event)

        # Generate hourly slots
        available_slots = []
        current = day_start
        while current < day_end:
            slot_end = current + timedelta(hours=1)
            if slot_end > day_end:
                slot_end = day_end
            # Check if this slot is available
            slot_available = True
            for event in day_events:
                event_start = event['start_time']
                event_end = event['end_time']
                if current < event_end and slot_end > event_start:
                    slot_available = False
                    break
            if slot_available:
                available_slots.append((current, slot_end))
            current += timedelta(hours=1)

        return available_slots

    def get_upcoming_events(self, num_events):
        now = datetime.now()
        upcoming = []
        for event in self.events:
            if event['start_time'] > now:
                upcoming.append(event)
        upcoming.sort(key=lambda e: e['start_time'])
        return upcoming[:num_events]

