                    if x1 == x0:
                        interp_val = y0
                    else:
                        t = (xi - x0) / (x1 - x0)
                        interp_val = y0 + t * (y1 - y0)
                    interp_val = round(interp_val, 10)
                    break
            if interp_val is not None:
                result.append(interp_val)
        return result

    @staticmethod
    def interpolate_2d(x, y, z, x_interp, y_interp):
