            for i in range(len(x) - 1):
                x0, x1 = x[i], x[i+1]
                if (x0 <= xi <= x1) or (x1 <= xi <= x0):
                    x_idx = i
                    break
            if x_idx is None:
                continue
            # Find y interval
            y_idx = None
            for j in range(len(y) - 1):
                y0, y1 = y[j], y[j+1]
                if (y0 <= yi <= y1) or (y1 <= yi <= y0):
                    y_idx = j
                    break
            if y_idx is None:
                continue
            i, j = x_idx, y_idx
            x0, x1 = x[i], x[i+1]
            y0, y1 = y[j], y[j+1]
            tx = (xi - x0) / (x1 - x0) if x1 != x0 else 0
            ty = (yi - y0) / (y1 - y0) if y1 != y0 else 0
            z00 = z[i][j]
