                # We need to check: all non-mine cells are revealed
                # '-' means unrevealed, 'X' means mine flagged or mine
                # The win condition: only mines remain as '-' or 'X' in player map
        # Check if all non-mine cells are revealed
        for r in range(n):
            for c in range(n):
                if self.minesweeper_map[r][c] != 'X':
                    if map[r][c] == '-':
                        return False
        return True

    def sweep(self, x, y):
        cell = self.minesweeper_map[x][y]
        if cell == 'X':
            # Hit a mine
            return False
        else:
            self.player_map[x][y] = cell
            self.score += 1
