                if not digit_str:
                    return ''.join(out)
                if is_hex:
                    if all(self.is_hex_char(c) for c in digit_str):
                        out.append(chr(int(digit_str, 16)))
                    else:
                        return ''.join(out)
                else:
                    if all(c.isdigit() for c in digit_str):
                        out.append(chr(int(digit_str)))
                    elif all(self.is_hex_char(c) for c in digit_str):
                        return ''.join(out)
                    else:
                        out.append(string[start:start + 2 + len(digit_str) + (1 if (start + 2 + len(digit_str) < len(string) and string[start + 2 + len(digit_str)] == ';') else 0)])
            else:
                out.append(string[i])
                i += 1
        return ''.join(out)

    @staticmethod
    def is_hex_char(char):
        return char in '0123456789abcdefABCDEF'"
}
