class Order:
    """
    The class manages restaurant orders by allowing the addition of dishes, calculation of the total cost, and checkout.
    """

    def __init__(self):
        self.menu = []
        self.selected_dishes = []
        self.sales = {}

    def add_dish(self, dish):
        # If menu is empty, just add the dish directly
        if not self.menu:
            self.selected_dishes.append(dish)
            return True

        dish_name = dish.get("dish")
        dish_count = dish.get("count", 0)

        # Find the dish in the menu
        for menu_dish in self.menu:
            if menu_dish["dish"] == dish_name:
                if menu_dish["count"] >= dish_count:
                    menu_dish["count"] -= dish_count
                    self.selected_dishes.append(dish)
                    return True
                else:
                    return False

        # Dish not found in menu
        self.selected_dishes.append(dish)
        return True

    def calculate_total(self):
        total = 0
        for selected in self.selected_dishes:
            dish_name = selected["dish"]
            price = selected["price"]
            count = selected["count"]
            sale = self.sales.get(dish_name, 1)
            total += price * count * sale
        return total

    def checkout(self):
        if not self.selected_dishes:
            return False
        total = self.calculate_total()
        self.selected_dishes = []
        return total

