class PushBoxGame:
    """
    This class implements a functionality of a sokoban game, where the player needs to move boxes to designated targets in order to win.
    """

    def __init__(self, map):
        self.map = map
        self.player_row = 0
        self.player_col = 0
        self.targets = []
        self.boxes = []
        self.target_count = 0
        self.is_game_over = False
        self.init_game()

    def init_game(self):
        for r, row in enumerate(self.map):
            for c, ch in enumerate(row):
                if ch == 'O':
                    self.player_row = r
                    self.player_col = c
                elif ch == 'G':
                    self.targets.append((r, c))
                elif ch == 'X':
                    self.boxes.append((r, c))
        self.target_count = len(self.targets)

    def check_win(self):
        for box in self.boxes:
            if box not in self.targets:
                self.is_game_over = False
                return self.is_game_over
        self.is_game_over = True
        return self.is_game_over

    def move(self, direction):
        direction_map = {
            'w': (-1, 0),
            's': (1, 0),
            'a': (0, -1),
            'd': (0, 1)
        }
        if direction not in direction_map:
            return self.is_game_over

        dr, dc = direction_map[direction]
        new_row = self.player_row + dr
        new_col = self.player_col + dc

        # Check bounds and wall
        if new_row < 0 or new_row >= len(self.map) or new_col < 0 or new_col >= len(self.map[new_row]):
            return self.is_game_over
        if self.map[new_row][new_col] == '#':
            return self.is_game_over

        # Check if there's a box at new position
        if (new_row, new_col) in self.boxes:
            box_new_row = new_row + dr
            box_new_col = new_col + dc
            # Check if box can be pushed
            if box_new_row < 0 or box_new_row >= len(self.map) or box_new_col < 0 or box_new_col >= len(self.map[box_new_row]):
                return self.is_game_over
            if self.map[box_new_row][box_new_col] == '#':
                return self.is_game_over
            if (box_new_row, box_new_col) in self.boxes:
                return self.is_game_over
            # Move the box
            box_idx = self.boxes.index((new_row, new_col))
            self.boxes[box_idx] = (box_new_row, box_new_col)

        # Move the player
        self.player_row = new_row
        self.player_col = new_col

        return self.check_win()

    def print_map(self):
        for r, row in enumerate(self.map):
            line = ''
            for c, ch in enumerate(row):
                if r == self.player_row and c == self.player_col:
                    line += 'O '
                elif (r, c) in self.boxes:
                    line += 'X '
                elif ch == '#':
                    line += '# '
                elif (r, c) in self.targets:
                    line += 'G '
                else:
                    line += '  '
            print(line.rstrip())

