    """

    def __init__(self, url):
        self.url = url

    def get_scheme(self):
        if '://' not in self.url:
            return None
        return self.url.split('://')[0]

    def get_host(self):
        if '://' not in self.url:
            return None
        after_scheme = self.url.split('://')[1]
        # host is everything up to the first '/'
        if '/' in after_scheme:
            host = after_scheme.split('/')[0]
        else:
            host = after_scheme
        return host if host else None

    def get_path(self):
        if '://' not in self.url:
            return None
        after_scheme = self.url.split('://')[1]
        if '/' not in after_scheme:
            return None
        idx = after_scheme.index('/')
        path = after_scheme[idx:]
        return path if path else None

    def get_query_params(self):
        if '://' not in self.url:
            return None
        # Check if there's a query string
        if '?' not in self.url:
            return None
        query_string = self.url.split('?', 1)[1]
        # Remove fragment
        if '#' in query_string:
            query_string = query_string.split('#')[0]
        # Parse query params
        params = {}
        if not query_string:
            return params
        pairs = query_string.split('&')
        for pair in pairs:
            if '=' in pair:
                key, value = pair.split('=', 1)
                if key:
                    params[key] = value
        return params

    def get_fragment(self):
        if '#' not in self.url:
            return None
        fragment = self.url.split('#', 1)[1]
        return fragment if fragment else None

